    const settings = JSON.parse(fs.readFileSync('.claude/settings.local.json', 'utf8'));

    // Update customInstructions if empty or null
    const existingInstructions = settings.customInstructions || '';
    if (!existingInstructions || existingInstructions === 'null') {
