    const logPattern = 'Bash(echo*>>*workflow-execution.log:*)';
    if (!settings.alwaysApproveTools.includes(logPattern)) {
      settings.alwaysApproveTools.push(logPattern);
      console.log('      ✓ Auto-approval added for workflow logs');
