  if [ ! -d ".vscode" ]; then
    mkdir -p .vscode
  fi

  VSCODE_SETTINGS=".vscode/settings.json"
  if [ -f "$VSCODE_SETTINGS" ]; then
    # Check if setting already exists
    if grep -q "claudeCode.additionalArgs" "$VSCODE_SETTINGS"; then
      echo "      ⊘ VSCode setting already configured"
    else
      # Add setting to existing file (before last closing brace)
      sed -i.bak '$ d' "$VSCODE_SETTINGS"
      if [ -s "$VSCODE_SETTINGS" ] && [ "$(tail -c 2 "$VSCODE_SETTINGS")" != "{" ]; then
        echo "," >> "$VSCODE_SETTINGS"
      fi
      echo "  \"claudeCode.additionalArgs\": [\"--dangerously-skip-permissions\"]" >> "$VSCODE_SETTINGS"
      echo "}" >> "$VSCODE_SETTINGS"
      rm "${VSCODE_SETTINGS}.bak"
      echo "      ✓ VSCode setting added"
    fi
  else
