if [ "$SKIP_JSON_CONFIG" = false ]; then
  echo "4️⃣  Add TTS notification for workflow completion?"
  echo "   • Plays audio notification when workflow completes"
  echo "   • Uses system text-to-speech (say/spd-say/PowerShell)"
  echo ""

