        ;;
    esac
  done
  echo ""

  if [ "$ENABLE_TTS" = true ]; then
    echo "   🔊 Configuring TTS completion notification..."

    # Detect OS
    OS_TYPE="unknown"
    if [[ "$OSTYPE" == "darwin"* ]]; then
      OS_TYPE="macos"
      TTS_CMD="say '작업 완료'"
    elif [[ "$OSTYPE" == "msys"* ]] || [[ "$OSTYPE" == "win32"* ]] || [[ "$OSTYPE" == "cygwin"* ]]; then
      OS_TYPE="windows"
      TTS_CMD='powershell -Command "[console]::beep(800,300)"'
    elif command -v spd-say &> /dev/null; then
      OS_TYPE="linux-speechd"
      TTS_CMD="spd-say '작업 완료'"
    elif command -v espeak &> /dev/null; then
      OS_TYPE="linux-espeak"
      TTS_CMD="espeak '작업 완료'"
    else
      OS_TYPE="unknown"
      TTS_CMD="echo '🔔 작업 완료!'"
    fi

    echo "      Detected OS: $OS_TYPE"

