        const hookContent = \`
📢 워크플로우 작업이 완료되었습니다!

다음 명령어를 실행하여 알림을 재생하세요:

\\`\\`\\`bash
${ttsCommand}
\\`\\`\\`

또는 아래 명령어를 복사하세요:

BASH_TO_RUN: ${ttsCommand}
\`.trim();

        // Check if agent-done-hook exists
        const existingHook = settings.hooks['agent-done-hook'] || '';

        if (existingHook && existingHook.trim() !== '') {
          console.log('      ⚠️  Existing agent-done-hook found');
          console.log('      💡 TTS command will be appended');
          settings.hooks['agent-done-hook'] = existingHook + '\n\n---\n\n' + hookContent;
        } else {
          settings.hooks['agent-done-hook'] = hookContent;
        }

        fs.writeFileSync('.claude/settings.local.json', JSON.stringify(settings, null, 2));
        console.log('      ✓ TTS notification hook added');
        console.log('      ✓ TTS command: ${ttsCommand}');
      " 2>/dev/null || echo "      ⚠️  Failed to configure TTS hook"
